<?php
namespace Tests\Feature;
use App\Models\{Pillar,Product,Event,Customer,User};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class PublicFlowsTest extends TestCase {
 use RefreshDatabase;
 public function test_visitor_can_send_inquiry(): void { $pillar=Pillar::create(['name'=>'Digital','slug'=>'digital','description'=>'Solusi digital']);$product=Product::create(['pillar_id'=>$pillar->id,'name'=>'Website','slug'=>'website','description'=>'Website bisnis','price_type'=>'negosiasi']);$this->post('/kontak',['name'=>'Nadia','email'=>'nadia@example.test','phone'=>'08123456789','segment'=>'umkm','organization'=>'Kedai','product_id'=>$product->id,'message'=>'Saya ingin membuat website untuk bisnis.'])->assertRedirect('/kontak');$this->assertDatabaseHas('customers',['email'=>'nadia@example.test']);$this->assertDatabaseHas('inquiries',['message'=>'Saya ingin membuat website untuk bisnis.','product_id'=>$product->id]); }
 public function test_event_registration_rejects_duplicate_email(): void { $pillar=Pillar::create(['name'=>'Edu','slug'=>'edu','description'=>'Edukasi']);$event=Event::create(['pillar_id'=>$pillar->id,'title'=>'Kelas Web','type'=>'bootcamp','description'=>'Kelas','start_at'=>now()->addWeek(),'location'=>'Jakarta','quota'=>2,'fee'=>0,'status'=>'buka']);$payload=['name'=>'Ari','email'=>'ari@example.test','phone'=>'08123456789','organization'=>'Sekolah'];$this->post("/event/{$event->id}/daftar",$payload)->assertSessionHasNoErrors();$this->post("/event/{$event->id}/daftar",$payload)->assertSessionHasErrors('email');$this->assertDatabaseCount('event_registrations',1);$this->assertSame('buka',$event->fresh()->status); }
 public function test_event_rejects_registration_when_quota_is_full(): void { $pillar=Pillar::create(['name'=>'Edu','slug'=>'edu','description'=>'Edukasi']);$event=Event::create(['pillar_id'=>$pillar->id,'title'=>'Kelas Web','type'=>'bootcamp','description'=>'Kelas','start_at'=>now()->addWeek(),'location'=>'Jakarta','quota'=>1,'fee'=>0,'status'=>'buka']);$this->post("/event/{$event->id}/daftar",['name'=>'Ari','email'=>'ari@example.test','phone'=>'08123456789'])->assertSessionHasNoErrors();$this->assertSame('penuh',$event->fresh()->status);$this->post("/event/{$event->id}/daftar",['name'=>'Budi','email'=>'budi@example.test','phone'=>'08123456780'])->assertSessionHasErrors('email');$this->assertDatabaseCount('event_registrations',1); }
 public function test_event_registration_rejects_closed_event(): void { $pillar=Pillar::create(['name'=>'Edu','slug'=>'edu','description'=>'Edukasi']);$event=Event::create(['pillar_id'=>$pillar->id,'title'=>'Kelas Web','type'=>'seminar','description'=>'Kelas','start_at'=>now()->addWeek(),'location'=>'Jakarta','quota'=>1,'fee'=>0,'status'=>'draft']);$this->post("/event/{$event->id}/daftar",['name'=>'Ari','email'=>'ari@example.test','phone'=>'08123456789'])->assertSessionHasErrors('email');$this->assertDatabaseCount('event_registrations',0); }
 public function test_admin_area_rejects_guest(): void { $this->get('/admin')->assertRedirect('/login'); }
 public function test_public_registration_is_disabled(): void { $this->get('/register')->assertNotFound(); }
 public function test_public_pages_render(): void { foreach(['/','/produk','/portofolio','/event','/tentang','/kontak'] as $path)$this->get($path)->assertOk(); }
 public function test_product_and_event_details_render(): void { $product=Product::factory()->create();$event=Event::factory()->create();$this->get(route('product',$product->slug))->assertOk()->assertSee($product->name);$this->get(route('event',$event))->assertOk()->assertSee($event->title); }
 public function test_admin_can_view_dashboard_and_product_form(): void { $user=User::factory()->create(['role'=>'admin']);$this->actingAs($user)->get('/admin')->assertOk();$this->actingAs($user)->get('/admin/content/products/create')->assertOk(); }
}
